import { useEffect, useMemo, useState } from "react";
import { CalendarDays, ChevronLeft, ChevronRight, ExternalLink, Info, RefreshCw, Search, SlidersHorizontal, X } from "lucide-react";
import { aiChainRows, assetScores, correlationForSeries, correlationUniverse, defaultPortfolioWeights, eventRows, fallbackHistory, lastChange, marketRiskAppetite, navigation, portfolioRiskAnalytics, pringCycle, pringStages, type AssetScore, type DashboardData, type EtfFlowRow, type HistorySeries } from "../lib/dashboard";

const sectionTitles: Record<string, [string, string]> = {
  overview: ["全球资产配置驾驶舱", "风险、周期、轮动与事件的一页晨会结论"],
  allocation: ["资产配置打分", "把跨资产行情转化为可执行的风险偏好判断"],
  regime: ["普林格经济周期时钟", "用债券、股票与商品的趋势顺序识别六阶段周期"],
  correlation: ["相关性与轮动矩阵", "识别分散化是否失效，以及跨资产共振"],
  markets: ["全球市场快照", "权益、利率、商品、汇率与AI主题横向比较"],
  "etf-flows": ["全球市场资金流", "从ETF一级市场申赎、共同基金与跨境证券流观察资金迁移"],
  "ai-chain": ["AI产业链深度监控", "从算力、云、电力到应用和材料的全链条信号"],
  calendar: ["全球事件日历", "按日期追踪政策、通胀、就业、能源与中国宏观"],
  research: ["大宗商品跟踪", "覆盖能源、金属、黑色、农产品、软商品与CFTC仓位"],
};

type SearchItem = { id: string; label: string; code: string; category: string; href: string; keywords: string };
const searchItems: SearchItem[] = [
  ...navigation.map((item) => ({ id: `page:${item.key}`, label: item.label, code: "分析页", category: "研究模块", href: item.href, keywords: sectionTitles[item.key]?.join(" ") ?? "" })),
  { id: "nvda", label: "英伟达", code: "NVDA", category: "AI芯片", href: "/ai-chain", keywords: "NVIDIA GPU 算力" },
  { id: "gold", label: "黄金", code: "GC / GLD", category: "贵金属", href: "/research", keywords: "金价 gold" },
  { id: "rebar", label: "螺纹钢", code: "RBM", category: "黑色系", href: "/research", keywords: "钢材 建筑需求" },
  { id: "oil", label: "原油", code: "WTI / Brent", category: "能源", href: "/research", keywords: "石油 EIA OPEC" },
  { id: "us10y", label: "美国长期国债", code: "TLT / US10Y", category: "利率", href: "/regime", keywords: "美债 收益率" },
  { id: "csi300", label: "沪深300ETF", code: "ASHR", category: "A股", href: "/markets", keywords: "沪深 A股" },
  { id: "fomc", label: "FOMC议息会议", code: "FOMC", category: "宏观事件", href: "/calendar", keywords: "美联储 利率决议" },
];

const formatNumber = (value: unknown, digits = 2) => { const n = Number(value); return Number.isFinite(n) ? n.toLocaleString("zh-CN", { maximumFractionDigits: digits }) : "-"; };
const pct = (value: unknown) => { const n = Number(value); return Number.isFinite(n) ? `${n >= 0 ? "+" : ""}${n.toFixed(2)}%` : "-"; };
const compactMoney = (value: unknown) => { if (value === null || value === undefined) return "建立基线"; const n = Number(value); if (!Number.isFinite(n)) return "建立基线"; const sign = n >= 0 ? "+" : "-", absolute = Math.abs(n); return `${sign}$${absolute >= 1e9 ? `${(absolute / 1e9).toFixed(2)}B` : `${(absolute / 1e6).toFixed(1)}M`}`; };
const tone = (value: number) => value > 0 ? "up" : value < 0 ? "down" : "flat";

function StatusPill({ children, kind = "neutral" }: { children: React.ReactNode; kind?: string }) { return <span className={`status-pill ${kind}`}>{children}</span>; }
function Panel({ title, kicker, children, action, className = "" }: { title: string; kicker?: string; children: React.ReactNode; action?: React.ReactNode; className?: string }) { return <section className={`terminal-panel ${className}`}><header className="panel-head"><div>{kicker && <span>{kicker}</span>}<h2>{title}</h2></div>{action}</header>{children}</section>; }
function MiniLine({ series }: { series: HistorySeries }) { const points = series.points.slice(-40); if (!points.length) return null; const min = Math.min(...points.map((item) => item.close)), max = Math.max(...points.map((item) => item.close)); const coords = points.map((item, index) => `${index / Math.max(1, points.length - 1) * 100},${34 - (item.close - min) / Math.max(.001, max - min) * 30}`).join(" "); return <svg className="mini-line" viewBox="0 0 100 36" preserveAspectRatio="none"><polyline points={coords} /></svg>; }

function ScoreBoard({ data, history }: { data: DashboardData; history: HistorySeries[] }) {
  const scores=assetScores(data,history),core=scores.filter(item=>item.group==="core"),equity=scores.filter(item=>item.group==="equity");
  const cards=(items:AssetScore[])=><div className={`score-grid score-grid-${items.length}`}>{items.map(item=><Link className="score-card" href={`/allocation/${item.key}/`} key={item.key}><div className="score-top"><strong>{item.asset}</strong><StatusPill kind={item.score>=79?"positive":item.score<67?"negative":"neutral"}>{item.view}</StatusPill></div><div className="score-number">{item.score}<small>/100</small></div><div className="score-meta"><span>历史综合分位 {item.percentile}%</span><span>置信度 {item.confidence}%</span></div><div className="score-track"><i style={{width:`${item.score}%`}} /></div><p>{item.driver}</p><small className="score-deep-link">查看评分拆解<ChevronRight size={12}/></small></Link>)}</div>;
  return <><details className="score-method"><summary>展开评分框架与计算口径</summary><div><strong>这是未来1至3个月的战术配置温度，不是考试分数，也不是收益保证。</strong><span>六项因子先转换为自身历史或同类横截面0至100分位，再按权重合成综合分位；展示分 = 60 + 0.30 × 综合分位，因此中性约75分、理论区间60至90分。</span><span>核心资产与权益卫星分层展示，全球股票、A股、港股和AI不再混合等权，避免重复计算权益风险。缺失、缓存或历史不足会降低置信度。</span></div></details><div className="score-group-label"><strong>一级资产</strong><span>互相独立的核心配置层</span></div>{cards(core)}<div className="score-group-label"><strong>权益内部配置</strong><span>A股、港股和AI属于股票子方向，不参与核心资产重复加总</span></div>{cards(equity)}</>;
}

function PringBoard({ data, history }: { data: DashboardData; history: HistorySeries[] }) {
  const cycle = pringCycle(data, history);
  return <><div className="pring-layout"><div className="pring-wheel"><Link className="pring-center" href="/regime/analysis/" aria-label={`查看阶段${cycle.stage}${cycle.name}的判定依据`}><small>当前阶段</small><strong>{cycle.stage}</strong><span>{cycle.name}</span><em>查看依据</em></Link>{pringStages.map((item) => cycle.stage===item.stage?<Link className={`pring-stage stage-${item.stage} active`} href="/regime/analysis/" key={item.stage}><b>{item.stage}</b><span>{item.name}</span></Link>:<div className={`pring-stage stage-${item.stage}`} key={item.stage}><b>{item.stage}</b><span>{item.name}</span></div>)}</div><div className="pring-signal-list"><div className="pring-confidence"><span>模型置信度</span><strong>{cycle.confidence}%</strong></div>{cycle.signals.map((signal) => <div className="pring-signal" key={signal.label}><span>{signal.label}</span><i><b className={tone(signal.value)} style={{ width: `${Math.min(100, Math.abs(signal.value) * 4 + 12)}%` }} /></i><strong className={tone(signal.value)}>{pct(signal.value)}</strong></div>)}<p>综合趋势采用20日35%与60日65%；点击当前阶段可查看代理资产、阶段拟合、宏观交叉验证与来源状态。</p><Link className="pring-audit-link" href="/regime/analysis/"><Info size={13}/>查看周期判定审计<ChevronRight size={13}/></Link></div></div><div className="regime-summary"><div><span>当前周期</span><strong>阶段{cycle.stage} · {cycle.name}</strong></div><div><span>优先关注</span><strong>{cycle.focus}</strong></div><div><span>相对回避</span><strong>{cycle.avoid}</strong></div></div></>;
}

function CorrelationMatrix({ history, days }: { history: HistorySeries[]; days: number }) {
  const visible = correlationUniverse(history);
  return <div className="matrix-wrap"><table className="matrix-table"><thead><tr><th>{days}日</th>{visible.map((item) => <th key={item.label}>{item.label}</th>)}</tr></thead><tbody>{visible.map((row) => <tr key={row.label}><th>{row.label}</th>{visible.map((column) => { const result=correlationForSeries(row,column,days),value=result.value,alpha=Math.abs(value)*.82+.08; return <td title={`${result.startDate} 至 ${result.endDate}，共同收益样本 ${result.sampleSize}`} key={column.label} style={{ background: value >= 0 ? `rgba(177,24,57,${alpha})` : `rgba(24,109,122,${alpha})`, color: Math.abs(value) > .46 ? "white" : "#22191b" }}>{value.toFixed(2)}</td>; })}</tr>)}</tbody></table></div>;
}

function MarketsTable({ data, history }: { data: DashboardData; history: HistorySeries[] }) {
  const quotes = new Map((data.fmp_quotes ?? []).map((item) => [item.symbol, item]));
  return <div className="data-table"><div className="table-row table-head"><span>资产</span><span>代码</span><span>最新</span><span>1日</span><span>20日</span><span>60日趋势</span><span>来源</span></div>{history.map((series) => { const quote = quotes.get(series.symbol), price = quote?.price ?? series.points.at(-1)?.close, daily = quote?.change_pct ?? lastChange(series), twenty = lastChange(series, 20); return <div className="table-row" key={series.symbol}><span><strong>{series.label}</strong><small>{series.name}</small></span><span className="mono">{series.symbol}</span><span className="mono">{formatNumber(price)}</span><span className={tone(daily ?? 0)}>{pct(daily)}</span><span className={tone(twenty)}>{pct(twenty)}</span><span><MiniLine series={series} /></span><a href={series.url} target="_blank" rel="noreferrer">{series.source}<ExternalLink size={12} /></a></div>; })}</div>;
}

function OverviewPage({ data, history }: { data: DashboardData; history: HistorySeries[] }) {
  const scores=assetScores(data,history),cycle=pringCycle(data,history),events=eventRows(data),sorted=scores.slice().sort((a,b)=>b.score-a.score),nextHigh=events.find(item=>item.importance==="高")??events[0],risk=marketRiskAppetite(data,history);
  return <><div className="decision-strip"><div><span>市场风险偏好</span><strong>{risk.score} · {risk.label}</strong></div><div><span>普林格阶段</span><strong>{cycle.stage} · {cycle.name}</strong></div><div><span>最强配置方向</span><strong>{sorted[0].asset} {sorted[0].score}</strong></div><div><span>最弱配置方向</span><strong>{sorted.at(-1)!.asset} {sorted.at(-1)!.score}</strong></div><div><span>下一高影响事件</span><strong>{nextHigh?`${nextHigh.date.slice(5)} ${nextHigh.event}`:"待官方更新"}</strong></div></div><div className="page-grid"><Panel title="资产配置打分" kicker="CROSS-ASSET SCORE" className="span-2" action={<Link className="text-action" href="/allocation">查看模型<ChevronRight size={14}/></Link>}><ScoreBoard data={data} history={history}/></Panel><Panel title="普林格时钟" kicker="PRING CYCLE" action={<Link className="text-action" href="/regime/analysis/">判定依据<ChevronRight size={14}/></Link>}><PringBoard data={data} history={history}/></Panel><Panel title="20日相关性" kicker="CORRELATION" className="span-2" action={<Link className="text-action" href="/correlation/methodology/">方法与数据<ChevronRight size={14}/></Link>}><CorrelationMatrix history={history} days={20}/></Panel><Panel title="未来事件" kicker="EVENT WATCH"><div className="event-stack">{events.slice(0,4).map(item=><Link href="/calendar" key={item.date+item.event}><time>{item.date.slice(5)}</time><span><strong>{item.event}</strong><small>{item.assets}</small></span><StatusPill kind={item.importance==="高"?"negative":"neutral"}>{item.importance}</StatusPill></Link>)}</div></Panel><Panel title="市场轮动" kicker="GLOBAL ROTATION" className="span-3"><MarketsTable data={data} history={history.slice(0,6)}/></Panel></div></>;
}

function PortfolioRiskPanel({scores,history}:{scores:AssetScore[];history:HistorySeries[]}){
  const [open,setOpen]=useState(false),[weights,setWeights]=useState<Record<string,number>>(defaultPortfolioWeights),[submitted,setSubmitted]=useState(false),total=Object.values(weights).reduce((sum,value)=>sum+Number(value||0),0),analytics=submitted?portfolioRiskAnalytics(weights,scores,history):null;
  const update=(key:string,value:string)=>{setWeights(current=>({...current,[key]:Math.max(0,Math.min(100,Number(value)||0))}));setSubmitted(false)};
  const normalize=()=>{if(!total)return;setWeights(Object.fromEntries(Object.entries(weights).map(([key,value])=>[key,Number((value/total*100).toFixed(1))])));setSubmitted(false)};
  return <Panel title="个人组合风险诊断" kicker="PERSONAL PORTFOLIO" className="span-3" action={<button className="text-action method-toggle" onClick={()=>setOpen(value=>!value)}><SlidersHorizontal size={14}/>{open?"收起持仓":"配置我的持仓"}</button>}><div className="personal-intro"><strong>仅在你主动填写并提交后生成</strong><span>计算保存在当前页面会话，不会影响其他用户。默认示例为核心全球股票30%、债券30%，其余为分散与卫星仓位。</span></div>{open&&<div className="portfolio-editor"><div className="weight-grid">{scores.map(item=><label key={item.key}><span>{item.asset}<small>{item.group==="core"?"一级资产":"权益卫星"}</small></span><input type="number" min="0" max="100" step="1" value={weights[item.key]??0} onChange={event=>update(item.key,event.target.value)}/><em>%</em></label>)}</div><div className="portfolio-actions"><span className={Math.abs(total-100)<.2?"valid":"invalid"}>当前合计 {formatNumber(total,1)}%</span><button onClick={normalize}>按比例归一至100%</button><button className="primary" disabled={Math.abs(total-100)>.2} onClick={()=>setSubmitted(true)}>生成组合诊断</button></div></div>}{analytics&&<div className="portfolio-result"><div className="portfolio-kpis"><div><span>配置吸引力</span><strong>{analytics.allocationScore}</strong><small>按持仓加权的配置温度</small></div><div><span>估算年化波动</span><strong>{analytics.volatility}%</strong><small>{analytics.label}</small></div><div><span>历史最大回撤</span><strong className="down">{analytics.maxDrawdown}%</strong><small>共同样本 {analytics.sampleDays}日</small></div><div><span>持仓集中度</span><strong>{analytics.concentration}</strong><small>HHI，越低越分散</small></div></div><div className="risk-contribution"><strong>估算风险贡献</strong>{analytics.riskContributions.map(item=><div key={item.key}><span>{item.label}</span><i><b className={tone(item.value)} style={{width:`${Math.min(100,Math.abs(item.value))}%`}}/></i><em className={tone(item.value)}>{formatNumber(item.value,1)}%</em></div>)}</div><p className="portfolio-caveat">采用代表性ETF日收益协方差估算；负贡献表示该资产在当前样本中提供了组合对冲。不包含税费、杠杆、汇率对冲及具体证券差异，结果不是投资建议。</p></div>}</Panel>;
}

function ModelMethodology(){return <details className="model-methodology"><summary>完整模型、评分公式与可靠性边界</summary><div className="methodology-body"><section><strong>1. 评分目标与公式</strong><p>目标是未来1至3个月的风险调整后战术配置吸引力。每个原始指标转换为0至100分位，综合分位 P = Σ(因子分位 × 权重)；页面展示分 S = 60 + 0.30 × P。中性约75，理论区间60至90，不强制产生最高分或最低分。</p></section><section><strong>2. 六项因子</strong><p>20日趋势25%、60日趋势15%、宏观适配20%、资金流或仓位15%、相对全球股票强弱15%、波动率约束10%。资产详情页公开每项观测值、日期、来源、分位、权重及贡献。</p></section><section><strong>3. 分位与宏观阈值</strong><p>价格、相对强弱和波动率使用代理ETF自身滚动历史分位；ETF流量使用同批ETF的流量/AUM横截面分位；CFTC使用净仓/未平仓横截面分位。宏观变化以20bp利率/信用变化、0.5点工业生产变化作为一个标准尺度映射，方向按资产经济含义预先固定。</p></section><section><strong>4. 层级与防止重复</strong><p>全球股票、债券、商品、黄金和美元属于一级资产；AI、港股和A股属于权益内部卫星方向。市场风险偏好不再平均八张评分卡，避免重复计算权益暴露。</p></section><section><strong>5. 置信度与限制</strong><p>置信度由因子覆盖和历史长度共同决定。公开接口失败、数据缓存或样本不足会降低置信度。宏观与资金流更新频率不同，模型不会把低频数据标成实时，也不会以代理ETF冒充完整市场数据库。</p></section><section><strong>6. 回测纪律</strong><p>历史表只验证可获得完整历史的价格子模型，使用当时及以前的数据并观察未来20日；宏观发布时点和ETF份额历史尚未完整归档前，不把它们事后填入回测。完整模型与价格子模型的验证范围在页面中分开标明。</p></section></div></details>}

function AllocationPage({data,history}:{data:DashboardData;history:HistorySeries[]}){
  const scores=assetScores(data,history),risk=marketRiskAppetite(data,history),backtest=data.score_backtest??[];
  return <div className="page-grid"><Panel title="八类资产配置温度" kicker="ALLOCATION SCORE" className="span-2"><ScoreBoard data={data} history={history}/></Panel><Panel title="市场风险偏好" kicker="MARKET RISK APPETITE"><div className="dial"><strong>{risk.score}</strong><span>{risk.label}</span><small>独立市场环境指标，不是八类资产平均</small></div><div className="risk-factor-list">{risk.factors.map(item=><div key={item.label}><span>{item.label}<small>权重 {item.weight}%</small></span><i><b style={{width:`${item.value}%`}}/></i><strong>{item.value}</strong></div>)}</div></Panel><Panel title="模型透明度" kicker="METHODOLOGY" className="span-3"><ModelMethodology/></Panel><PortfolioRiskPanel scores={scores} history={history}/><Panel title="价格子模型历史校准" kicker="MODEL VALIDATION" className="span-3"><details className="score-method"><summary>查看回测范围与防前视处理</summary><div><strong>这里只验证具有连续历史的价格子模型，不冒充完整六因子回测。</strong><span>技术信号达到自身历史前40%时观察随后20个交易日收益；只使用信号日及以前数据。后续积累带真实发布时间的宏观与份额历史后，再逐步扩展完整模型验证。</span></div></details><div className="data-table backtest-table"><div className="table-row table-head"><span>资产</span><span>代理</span><span>20日命中率</span><span>信号后均值</span><span>区间最大回撤</span><span>当前历史分位</span><span>有效样本</span></div>{backtest.map(item=><div className="table-row" key={item.asset}><strong>{item.asset}</strong><span className="mono">{item.symbol}</span><span>{item.hit_rate_20d===null?"建立样本":`${formatNumber(item.hit_rate_20d,1)}%`}</span><span className={tone(item.avg_forward_return_20d??0)}>{item.avg_forward_return_20d===null?"-":pct(item.avg_forward_return_20d)}</span><span className="down">{formatNumber(item.max_drawdown,1)}%</span><span>{formatNumber(item.current_percentile,0)}%</span><span>{item.sample_size}</span></div>)}</div></Panel></div>;
}

function AllocationDetailPage({data,history,detail}:{data:DashboardData;history:HistorySeries[];detail:string}){
  const scores=assetScores(data,history),item=scores.find(score=>score.key===detail)??scores[0],symbols=item.proxy.split(" / "),series=history.find(row=>symbols.includes(row.symbol))??history.find(row=>item.key==="equity"&&row.symbol==="SPY"),flows=(data.etf_fund_flows??[]).filter(row=>symbols.includes(row.symbol)||(item.key==="china-a"&&["MCHI","EEM"].includes(row.symbol))),macroFactors=item.factors.filter(factor=>factor.bucket==="宏观"||factor.bucket==="资金/仓位"),backtest=(data.score_backtest??[]).find(row=>row.asset===item.asset||row.symbol===series?.symbol);
  return <div className="allocation-detail"><div className="allocation-breadcrumb"><Link href="/allocation/">资产打分</Link><ChevronRight size={13}/><strong>{item.asset}</strong></div><div className="detail-hero"><div><span>{item.group==="core"?"一级核心资产":"权益内部卫星方向"}</span><h2>{item.asset}配置研究</h2><p>{item.description}</p></div><div className="detail-score"><strong>{item.score}</strong><span>{item.view}</span><small>综合分位 {item.percentile}% · 置信度 {item.confidence}%</small></div></div><div className="page-grid"><Panel title="本期结论" kicker="ALLOCATION VIEW" className="span-2"><div className="detail-thesis"><div><strong>为什么得到这个分数</strong><p>{item.driver}。当前得分由下列六项公开因子逐项加权，没有使用八资产当日强制排名。</p></div><div className="thesis-columns"><section><strong>主要支撑</strong>{item.positives.length?item.positives.map(text=><span key={text}>{text}</span>):<span>暂无达到60分位的明确支撑项</span>}</section><section><strong>主要约束</strong>{item.risks.length?item.risks.map(text=><span key={text}>{text}</span>):<span>暂无低于40分位的明确约束项</span>}</section></div></div></Panel><Panel title="行情与样本" kicker="MARKET PROXY">{series?<div className="detail-market"><div><span>主要代理</span><strong>{series.symbol}</strong><small>{series.name}</small></div><MiniLine series={series}/><div className="detail-returns"><span>20日 <b className={tone(lastChange(series,20))}>{pct(lastChange(series,20))}</b></span><span>60日 <b className={tone(lastChange(series,60))}>{pct(lastChange(series,60))}</b></span><span>历史 {series.points.length}日</span></div><a href={series.url} target="_blank" rel="noreferrer">{series.source}<ExternalLink size={12}/></a></div>:<p className="large-note">主要代理行情尚未取得，相关因子按中性处理并降低置信度。</p>}</Panel><Panel title="评分因子逐项拆解" kicker="FACTOR ATTRIBUTION" className="span-3"><div className="factor-attribution"><div className="factor-row factor-head"><span>因子 / 类别</span><span>最新观测</span><span>分位</span><span>权重</span><span>加权贡献</span><span>数据日 / 来源</span></div>{item.factors.map(factor=><div className={`factor-row ${factor.available?"":"missing"}`} key={factor.key}><span><strong>{factor.label}</strong><small>{factor.bucket} · {factor.logic}</small></span><span>{factor.observed}</span><span><i><b style={{width:`${factor.percentile}%`}}/></i>{factor.percentile}</span><span>{factor.weight}%</span><strong>{factor.contribution.toFixed(1)}</strong>{factor.url.startsWith("/")?<Link href={factor.url}>{factor.as_of}<small>{factor.source} · {factor.status}</small></Link>:<a href={factor.url} target="_blank" rel="noreferrer">{factor.as_of}<small>{factor.source} · {factor.status}</small></a>}</div>)}</div></Panel><Panel title="宏观与资金验证" kicker="CROSS CHECK" className="span-2"><div className="cross-check-grid">{macroFactors.map(factor=><div key={factor.key}><span>{factor.label}</span><strong>{factor.observed}</strong><small>{factor.source} · {factor.as_of} · {factor.status}</small></div>)}{flows.map(flow=><div key={flow.symbol}><span>{flow.symbol}估算净申赎</span><strong className={tone(flow.flow_5d??flow.estimated_flow??0)}>{compactMoney(flow.flow_5d??flow.estimated_flow)}</strong><small>{flow.as_of} · {flow.issuer} · {flow.data_status??"online"}</small></div>)}</div></Panel><Panel title="验证状态" kicker="MODEL VALIDATION"><div className="validation-card"><span>价格子模型</span><strong>{backtest?.hit_rate_20d===null||backtest?.hit_rate_20d===undefined?"积累样本":`${backtest.hit_rate_20d}% 命中率`}</strong><small>{backtest?`${backtest.sample_size}个有效信号 · 后20日均值 ${pct(backtest.avg_forward_return_20d)}`:"该代理尚无独立回测记录"}</small><p>宏观和资金流因子尚未拥有完整的历史发布时间序列，因此未事后填充进回测。</p></div></Panel>{item.key==="ai"&&<Panel title="产业链交叉验证" kicker="AI CHAIN" className="span-3"><div className="ai-cross-link"><span>本页回答“AI是否值得配置”；07模块回答“产业链内部配置哪里”。</span><Link href="/ai-chain/">进入AI产业链研究<ChevronRight size={14}/></Link></div></Panel>}<Panel title="本资产评分方法" kicker="AUDIT TRAIL" className="span-3"><ModelMethodology/></Panel></div></div>;
}

function RegimePage({ data, history }: { data: DashboardData; history: HistorySeries[] }) { return <div className="page-grid"><Panel title="普林格六阶段时钟" kicker="PRING CYCLE" className="span-2" action={<Link className="text-action" href="/regime/analysis/"><Info size={13}/>判定依据<ChevronRight size={13}/></Link>}><PringBoard data={data} history={history} /></Panel><Panel title="周期判定输入" kicker="TREND INPUTS"><div className="factor-list">{(data.fred_macro ?? []).filter((item) => ["INDPRO", "CPIAUCSL", "PPIACO", "DGS10", "T10Y2Y"].includes(item.series_id)).map((item) => <a href={item.url} target="_blank" rel="noreferrer" key={item.series_id}><span>{item.name}<small>{item.date}</small></span><strong>{formatNumber(item.value, 3)}</strong><em className={tone(item.change ?? 0)}>{formatNumber(item.change, 3)}</em></a>)}</div><p className="large-note">市场阶段由债券、股票、商品多代理组合的20日与60日趋势决定；工业生产、物价、利率和信用仅作交叉验证，不以滞后宏观数据覆盖市场信号。</p></Panel><Panel title="六阶段资产映射" kicker="ASSET PLAYBOOK" className="span-3"><div className="playbook-grid pring-playbook">{pringStages.map((item) => <div key={item.stage}><strong>{item.stage} · {item.name}</strong><span>关注：{item.focus}</span><small>回避：{item.avoid}</small></div>)}</div></Panel></div>; }

function PringDetailPage({data,history}:{data:DashboardData;history:HistorySeries[]}){
  const cycle=pringCycle(data,history),direction=(value:number)=>value>0?"上行":"下行",pattern=(values:readonly number[])=>values.map(value=>value>0?"↑":"↓").join("  "),macroSupport=cycle.macroChecks.filter(item=>item.verdict==="支持").length;
  return <div className="model-audit-page"><div className="allocation-breadcrumb"><Link href="/regime/">普林格时钟</Link><ChevronRight size={13}/><strong>周期判定审计</strong></div><div className="detail-hero regime-detail-hero"><div><span>PRING CYCLE AUDIT</span><h2>阶段{cycle.stage} · {cycle.name}</h2><p>当前市场组合方向为债券{direction(cycle.signals[0].value)}、股票{direction(cycle.signals[1].value)}、商品{direction(cycle.signals[2].value)}。模型以价格先行顺序识别阶段，宏观数据只验证、不直接决定结论。</p></div><div className="detail-score"><strong>{cycle.confidence}%</strong><span>判定置信度</span><small>阶段拟合 {cycle.fit}% · 数据日 {cycle.asOf}</small></div></div><div className="page-grid"><Panel title={`为什么判定为“${cycle.name}”`} kicker="DECISION RATIONALE" className="span-2"><div className="audit-rationale"><p>阶段{cycle.stage}的理论方向模板为 <b>{pattern(cycle.pattern)}</b>（债券 / 股票 / 商品），当前实际方向为 <b>{pattern(cycle.actualPattern)}</b>。三类资产中有 <strong>{cycle.supports.length}</strong> 类方向吻合。</p><div><section><span>吻合证据</span><strong>{cycle.supports.join("、")||"暂无"}</strong></section><section><span>相反证据</span><strong>{cycle.conflicts.join("、")||"暂无"}</strong></section></div><small>第二候选为阶段{cycle.runnerUp.stage}“{cycle.runnerUp.name}”，拟合度 {cycle.runnerUp.fit}%。候选差距越小，阶段边界越模糊。</small></div></Panel><Panel title="宏观验证概览" kicker="MACRO CONFIRMATION"><div className="audit-kpis"><div><span>支持项</span><strong>{macroSupport}/{cycle.macroChecks.length}</strong></div><div><span>最佳阶段拟合</span><strong>{cycle.fit}%</strong></div><div><span>第二候选拟合</span><strong>{cycle.runnerUp.fit}%</strong></div></div><p className="large-note">宏观指标存在发布滞后，因此只用于检查价格阶段是否获得基本面印证，不参与阶段选择。</p></Panel><Panel title="三类资产组合趋势" kicker="COMPOSITE TREND" className="span-3"><div className="cycle-signal-grid">{cycle.signals.map(signal=><div key={signal.label}><header><span>{signal.label}</span><StatusPill kind={signal.direction===signal.expected?"positive":"negative"}>{signal.direction===signal.expected?"符合模板":"偏离模板"}</StatusPill></header><strong className={tone(signal.value)}>{pct(signal.value)}</strong><small>20日 {pct(signal.return20)} · 60日 {pct(signal.return60)}</small><i><b style={{width:`${signal.agreement}%`}}/></i><em>内部方向一致性 {formatNumber(signal.agreement,0)}%</em></div>)}</div></Panel><Panel title="底层代理资产与权重" kicker="MARKET EVIDENCE" className="span-3"><div className="data-table pring-evidence-table"><div className="table-row table-head"><span>资产组 / 代理</span><span>组合权重</span><span>20日收益</span><span>60日收益</span><span>加权趋势</span><span>数据日</span><span>来源状态</span></div>{cycle.signals.flatMap(signal=>signal.components.map(component=><a className="table-row" href={component.url} target="_blank" rel="noreferrer" key={`${signal.label}-${component.symbol}`}><span><strong>{signal.label} · {component.symbol}</strong><small>{component.name}</small></span><span>{formatNumber(component.weight*100,1)}%</span><span className={tone(component.return20)}>{pct(component.return20)}</span><span className={tone(component.return60)}>{pct(component.return60)}</span><span className={tone(component.blended)}>{pct(component.blended)}</span><span>{component.date}</span><span><StatusPill kind={component.status==="online"?"positive":"neutral"}>{component.status}</StatusPill><small>{component.source}</small></span></a>))}</div></Panel><Panel title="六阶段拟合比较" kicker="MODEL COMPETITION" className="span-2"><div className="stage-fit-list">{cycle.stageFits.map((item,index)=><div className={index===0?"active":""} key={item.stage}><span><b>阶段{item.stage} · {item.name}</b><small>模板 {pattern(item.pattern)} · {item.matched}/3方向吻合</small></span><i><b style={{width:`${item.fit}%`}}/></i><strong>{item.fit}%</strong></div>)}</div></Panel><Panel title="FRED宏观交叉验证" kicker="FUNDAMENTAL CHECK"><div className="macro-check-list">{cycle.macroChecks.map(item=><a href={item.url} target="_blank" rel="noreferrer" key={item.id}><span><strong>{item.label}</strong><small>{item.rationale} · {item.date}</small></span><b className={tone(item.change??0)}>{item.change===null?"-":`${item.change>=0?"+":""}${formatNumber(item.change,3)}`}</b><StatusPill kind={item.verdict==="支持"?"positive":item.verdict==="冲突"?"negative":"neutral"}>{item.verdict}</StatusPill><small>{item.source} · {item.status}</small></a>)}</div></Panel><Panel title="模型、公式与可靠性边界" kicker="METHODOLOGY" className="span-3"><div className="methodology-body pring-methodology"><section><strong>1. 理论框架</strong><p>普林格六阶段框架观察债券、股票、商品依次见底与见顶。阶段模板依次为：+--、++-、+++、-++、--+、---。这里的正负代表价格组合趋势方向。</p></section><section><strong>2. 趋势公式</strong><p>{cycle.formula}。20日用于确认近期转折，60日承担更高权重以降低短期噪声。</p></section><section><strong>3. 组合构造</strong><p>债券使用AGG、IEF、TLT；股票使用ACWI、SPY、ASHR、EWH；商品使用DBC、CPER、USO及公开商品篮子。缺失代理按可用权重重新归一。</p></section><section><strong>4. 阶段选择</strong><p>每个阶段对三类资产计算方向相似度，拟合度最高者为当前阶段。页面同时公开第二候选，避免把接近边界的结果描述为确定事实。</p></section><section><strong>5. 置信度</strong><p>置信度综合最佳阶段拟合45%、代理内部一致性25%、数据来源状态20%、第一与第二候选差距10%，上限95%。</p></section><section><strong>6. 使用限制</strong><p>这是市场价格周期模型，不是GDP实时预测。ETF含地域、汇率和期限偏差；低频宏观数据有滞后；阶段切换附近可能反复，不能单独作为交易指令。</p></section></div></Panel></div></div>;
}

function CorrelationPage({data,history}:{data:DashboardData;history:HistorySeries[]}) { const [days, setDays] = useState(20); return <div className="page-grid"><Panel title="跨资产相关性矩阵" kicker="ROLLING CORRELATION" className="span-3" action={<div className="panel-actions"><div className="segmented"><button className={days === 20 ? "active" : ""} onClick={() => setDays(20)}>20日</button><button className={days === 60 ? "active" : ""} onClick={() => setDays(60)}>60日</button></div><Link className="text-action" href="/correlation/methodology/"><Info size={13}/>方法与数据</Link></div>}><CorrelationMatrix history={history} days={days} /><div className="matrix-legend"><span><i className="positive" />正相关</span><span><i className="negative" />负相关</span><small>按共同交易日对齐ETF收盘价，再以简单日收益率计算Pearson相关系数。</small><Link href="/correlation/methodology/">查看公式、样本与来源<ChevronRight size={12}/></Link></div></Panel><Panel title="轮动强弱" kicker="RELATIVE MOMENTUM" className="span-2"><div className="rotation-bars">{history.map((item) => ({ label: item.label, value: lastChange(item, days) })).sort((a, b) => b.value - a.value).map((item) => <div key={item.label}><span>{item.label}</span><div><i className={tone(item.value)} style={{ width: `${Math.min(100, Math.abs(item.value) * 6 + 8)}%` }} /></div><strong className={tone(item.value)}>{pct(item.value)}</strong></div>)}</div></Panel><Panel title="分散化提示" kicker="PORTFOLIO NOTE"><p className="large-note">当股债相关性同步转正、美元与黄金同涨时，传统分散化可能失效。相关性描述共同波动，不代表因果，且会随窗口和市场状态变化。</p></Panel></div>; }

function CorrelationDetailPage({data,history}:{data:DashboardData;history:HistorySeries[]}){
  const universe=correlationUniverse(history),status=String((data.source_status??[]).find(item=>item.key==="market_history")?.status??"unverified"),pairs=universe.flatMap((left,index)=>universe.slice(index+1).map(right=>({left,right,r20:correlationForSeries(left,right,20),r60:correlationForSeries(left,right,60),r252:correlationForSeries(left,right,252)}))).sort((a,b)=>Math.abs(b.r60.value)-Math.abs(a.r60.value)),interpret=(value:number)=>Math.abs(value)>=.7?`${value>0?"强正":"强负"}相关`:Math.abs(value)>=.4?`${value>0?"中等正":"中等负"}相关`:"弱相关";
  return <div className="model-audit-page"><div className="allocation-breadcrumb"><Link href="/correlation/">相关性矩阵</Link><ChevronRight size={13}/><strong>方法与数据审计</strong></div><div className="detail-hero correlation-detail-hero"><div><span>CORRELATION AUDIT</span><h2>跨资产相关性计算说明</h2><p>先按日期取两项资产共同收盘观测，再计算相邻共同交易日的简单收益率，最后在20、60和252个共同收益样本上计算Pearson相关系数。</p></div><div className="detail-score"><strong>{universe.length}</strong><span>代表性资产</span><small>{pairs.length}组两两关系 · 数据状态 {status}</small></div></div><div className="page-grid"><Panel title="计算公式" kicker="PEARSON CORRELATION" className="span-2"><div className="correlation-formula"><strong>ρ(X,Y) = Cov(X,Y) / [σ(X) × σ(Y)]</strong><p>其中 X、Y 为共同交易日上的收盘到收盘简单日收益率：rₜ = Pₜ / Pₜ₋₁ − 1。系数范围为 -1 至 +1；正值表示同向波动，负值表示反向波动，接近0表示线性联动较弱。</p></div></Panel><Panel title="计算纪律" kicker="DATA ALIGNMENT"><div className="audit-kpis"><div><span>日期处理</span><strong>交集对齐</strong></div><div><span>缺失值</span><strong>不填充</strong></div><div><span>价格口径</span><strong>日收盘</strong></div></div><p className="large-note">不同国家节假日造成的非共同日期会被剔除，不用“第N条记录”强行配对。</p></Panel><Panel title="当前两两相关性审计" kicker="PAIRWISE RESULTS" className="span-3"><div className="data-table correlation-audit-table"><div className="table-row table-head"><span>资产对 / 代理</span><span>20日相关</span><span>60日相关</span><span>252日相关</span><span>共同样本</span><span>区间</span><span>当前解释</span></div>{pairs.map(item=><div className="table-row" key={`${item.left.symbol}-${item.right.symbol}`}><span><strong>{item.left.label} / {item.right.label}</strong><small>{item.left.symbol} / {item.right.symbol}</small></span><span className={tone(item.r20.value)}>{item.r20.value.toFixed(2)}<small>n={item.r20.sampleSize}</small></span><span className={tone(item.r60.value)}>{item.r60.value.toFixed(2)}<small>n={item.r60.sampleSize}</small></span><span className={tone(item.r252.value)}>{item.r252.value.toFixed(2)}<small>n={item.r252.sampleSize}</small></span><span>{item.r60.sampleSize}</span><span>{item.r60.startDate}<small>至 {item.r60.endDate}</small></span><strong>{interpret(item.r60.value)}</strong></div>)}</div></Panel><Panel title="代理资产与来源" kicker="INPUT UNIVERSE" className="span-2"><div className="correlation-source-grid">{universe.map(item=><a href={item.url} target="_blank" rel="noreferrer" key={item.symbol}><span>{item.label}</span><strong>{item.symbol}</strong><small>{item.name}</small><em>{item.points.at(-1)?.date??"-"} · {item.source} · {status}</em></a>)}</div></Panel><Panel title="如何用于配置" kicker="INTERPRETATION"><div className="interpretation-list"><div><strong>|ρ| ≥ 0.70</strong><span>强联动，需要警惕名义分散、实际同向。</span></div><div><strong>0.40 ≤ |ρ| &lt; 0.70</strong><span>中等联动，可结合波动率和仓位权重评估。</span></div><div><strong>|ρ| &lt; 0.40</strong><span>线性联动较弱，但极端时期仍可能同时下跌。</span></div></div></Panel><Panel title="可靠性与限制" kicker="METHODOLOGY" className="span-3"><div className="methodology-body"><section><strong>1. 为什么按日期对齐</strong><p>美股、A股和商品的休市日不同。只按数组位置计算会把不同日期错误配对，因此模型先取日期交集。</p></section><section><strong>2. 为什么展示三种窗口</strong><p>20日反应快但噪声大，60日用于战术配置，252日提供约一年的结构背景。窗口不同出现差异是正常信息，不是计算错误。</p></section><section><strong>3. 代理偏差</strong><p>ETF价格可能包含费用、跟踪误差、交易时区和汇率影响；AGG或TLT并不代表全部全球债券，结果应按代理口径理解。</p></section><section><strong>4. 非因果关系</strong><p>相关性只描述线性共同波动，不证明一项资产导致另一项变化，也不能直接推断未来相关性。</p></section><section><strong>5. 极端状态</strong><p>压力时期相关性可能迅速趋同，历史低相关不保证危机中仍能对冲。组合风险还需结合波动率、尾部损失和流动性。</p></section><section><strong>6. 更新频率</strong><p>输入随公开日线更新；数据失败时沿用缓存并显示状态。页面不把非同步盘中报价混入日频矩阵。</p></section></div></Panel></div></div>;
}

function aggregateFlows(rows: EtfFlowRow[], key: "asset_class" | "region") { const groups = new Map<string, { label: string; day: number; five: number; twenty: number; aum: number; coverage: number; positive: number }>(); rows.forEach((row) => { const label = row[key] || "其他", current = groups.get(label) ?? { label, day: 0, five: 0, twenty: 0, aum: 0, coverage: 0, positive: 0 }; current.day += row.estimated_flow ?? 0; current.five += row.flow_5d ?? 0; current.twenty += row.flow_20d ?? 0; current.aum += row.aum ?? 0; current.coverage += 1; if ((row.estimated_flow ?? 0) > 0) current.positive += 1; groups.set(label, current); }); return [...groups.values()].sort((a, b) => b.five - a.five); }
function flowState(row: EtfFlowRow) { const history = row.history ?? [], current = Number(row.nav), past = Number(history.at(-6)?.nav ?? history[0]?.nav), navChange = current && past ? (current / past - 1) * 100 : 0, flow = row.flow_5d ?? row.estimated_flow ?? 0; if (flow >= 0 && navChange >= 0) return { label: "资金与价格共振", kind: "positive", navChange }; if (flow >= 0) return { label: "逆势申购", kind: "warning", navChange }; if (navChange >= 0) return { label: "上涨赎回", kind: "neutral", navChange }; return { label: "资金与价格走弱", kind: "negative", navChange }; }

function GlobalFlowsPage({ data }: { data: DashboardData }) {
  const flows = data.etf_fund_flows ?? [], computed = flows.filter((item) => item.estimated_flow !== null), classes = aggregateFlows(flows, "asset_class"), regions = aggregateFlows(flows, "region"), totalDay = computed.reduce((sum, item) => sum + (item.estimated_flow ?? 0), 0), totalFive = flows.reduce((sum, item) => sum + (item.flow_5d ?? 0), 0), totalTwenty = flows.reduce((sum, item) => sum + (item.flow_20d ?? 0), 0), breadth = computed.length ? computed.filter((item) => (item.estimated_flow ?? 0) > 0).length / computed.length * 100 : 0;
  return <div className="page-grid"><Panel title="资金流总览" kicker="FLOW MONITOR" className="span-3"><div className="flow-dashboard"><div><span>代表性ETF覆盖</span><strong>{flows.length}</strong><small>跨资产与主要地区</small></div><div><span>最新日估算净申赎</span><strong className={tone(totalDay)}>{compactMoney(totalDay)}</strong><small>一级市场份额变化口径</small></div><div><span>近5期累计</span><strong className={tone(totalFive)}>{compactMoney(totalFive)}</strong><small>各ETF披露日加总</small></div><div><span>近20期累计</span><strong className={tone(totalTwenty)}>{compactMoney(totalTwenty)}</strong><small>趋势观察，非全市场总额</small></div><div><span>申购广度</span><strong>{formatNumber(breadth, 0)}%</strong><small>最新净申购ETF占比</small></div></div></Panel><Panel title="资产类别流向" kicker="ASSET CLASS" className="span-2"><div className="data-table flow-aggregate-table"><div className="table-row table-head"><span>资产类别</span><span>覆盖</span><span>最新日</span><span>近5期</span><span>近20期</span><span>净申购广度</span></div>{classes.map((item) => <div className="table-row" key={item.label}><strong>{item.label}</strong><span>{item.coverage}只</span><span className={tone(item.day)}>{compactMoney(item.day)}</span><span className={tone(item.five)}>{compactMoney(item.five)}</span><span className={tone(item.twenty)}>{compactMoney(item.twenty)}</span><span>{formatNumber(item.positive / item.coverage * 100, 0)}%</span></div>)}</div></Panel><Panel title="区域轮动" kicker="REGIONAL ROTATION"><div className="regional-flow-list">{regions.map((item) => <div key={item.label}><span><strong>{item.label}</strong><small>{item.coverage}只代表ETF</small></span><b className={tone(item.five)}>{compactMoney(item.five)}</b></div>)}</div></Panel><Panel title="ETF一级市场明细" kicker="CREATION / REDEMPTION" className="span-3"><div className="data-table global-flow-table"><div className="table-row table-head"><span>ETF / 市场</span><span>类别</span><span>最新日</span><span>近5期</span><span>近20期</span><span>流量/AUM</span><span>NAV 5期</span><span>资金价格状态</span><span>数据日 / 来源</span></div>{flows.map((item) => { const state = flowState(item); return <div className="table-row" key={item.symbol}><span><strong>{item.symbol} · {item.asset}</strong><small>{item.region} / {item.segment}</small></span><span>{item.asset_class}</span><span className={tone(item.estimated_flow ?? 0)}>{compactMoney(item.estimated_flow)}</span><span className={tone(item.flow_5d ?? 0)}>{compactMoney(item.flow_5d)}</span><span className={tone(item.flow_20d ?? 0)}>{compactMoney(item.flow_20d)}</span><span>{item.flow_intensity === null || item.flow_intensity === undefined ? "-" : pct(item.flow_intensity)}</span><span className={tone(state.navChange)}>{pct(state.navChange)}</span><StatusPill kind={state.kind}>{state.label}</StatusPill><a href={item.url} target="_blank" rel="noreferrer">{item.as_of}<small>{item.issuer}</small><ExternalLink size={12} /></a></div>; })}</div></Panel><Panel title="美国长期基金周度流量" kicker="ICI OFFICIAL" className="span-2"><div className="data-table simple-flow-table"><div className="table-row table-head"><span>类别</span><span>净流量</span><span>频率</span><span>数据日</span><span>范围</span></div>{(data.ici_weekly_flows ?? []).map((item) => <a className="table-row" href={item.url} target="_blank" rel="noreferrer" key={item.category}><strong>{item.category}</strong><span className={tone(item.value_usd)}>{compactMoney(item.value_usd)}</span><span>{item.frequency}</span><span>{item.as_of}</span><small>{item.scope}</small></a>)}</div></Panel><Panel title="外国投资者买卖美国证券" kicker="US TREASURY TIC"><div className="data-table simple-flow-table"><div className="table-row table-head"><span>证券类别</span><span>净买入</span><span>频率</span><span>数据月</span><span>范围</span></div>{(data.tic_cross_border_flows ?? []).map((item) => <a className="table-row" href={item.url} target="_blank" rel="noreferrer" key={item.category}><strong>{item.category}</strong><span className={tone(item.value_usd)}>{compactMoney(item.value_usd)}</span><span>{item.frequency}</span><span>{item.as_of}</span><small>{item.scope}</small></a>)}</div></Panel><Panel title="口径与可用边界" kicker="DATA DISCIPLINE" className="span-3"><div className="method-grid"><div><strong>ETF一级市场</strong><p>估算净申赎 = 相邻披露日流通份额变化 × 当日NAV。接近创建赎回，但不是盘中成交方向。</p></div><div><strong>ICI官方统计</strong><p>美国长期共同基金周频估算，不含ETF，用于确认股票与债券基金的中期迁移。</p></div><div><strong>TIC官方统计</strong><p>外国投资者对美国长期证券的月频净买卖，发布时间滞后，不应标记为实时。</p></div><div><strong>当前无法免费覆盖</strong><p>EPFR式全球全基金、机构客户类型、行业日频与国家全口径流量仍需商业数据。页面不以代理值冒充完整数据库。</p></div></div></Panel></div>;
}

function AiPage({ data }: { data: DashboardData }) {
  const chain = aiChainRows(data), pricingTime = data.pricing_generated_at ? new Date(data.pricing_generated_at).toLocaleString("zh-CN", { timeZone: "Asia/Shanghai" }) : "随4H数据更新";
  return <div className="page-grid"><Panel title="AI全链条景气表" kicker="AI VALUE CHAIN" className="span-3"><div className="data-table chain-table"><div className="table-row table-head"><span>环节</span><span>细分</span><span>样本 / 龙头</span><span>平均涨跌</span><span>上涨家数</span><span>相对量</span><span>PE中位数</span><span>强度</span></div>{chain.map((item) => <div className="table-row" key={item.group}><StatusPill kind={item.segment === "上游" ? "negative" : item.segment === "中游" ? "warning" : "neutral"}>{item.segment}</StatusPill><strong>{item.group}</strong><span className="mono">{item.sample_size ?? "-"}只 · {item.leaders}</span><span className={tone(item.change)}>{pct(item.change)}</span><span>{item.breadth === undefined ? "-" : `${formatNumber(item.breadth, 0)}%`}</span><span>{item.relative_volume === undefined ? "-" : `${formatNumber(item.relative_volume, 2)}x`}</span><span>{item.valuation_pe ? `${formatNumber(item.valuation_pe, 1)}x` : "-"}</span><span><b className="strength">{item.strength}</b></span></div>)}</div></Panel><Panel title="AI产业链景气排名" kicker="CHAIN SIGNAL" className="span-3"><details className="chain-method"><summary>排名口径</summary><div>强度由代表成分股当日平均涨跌、上涨家数占比、成交量相对20日均量及PE中位数自动计算。缺失估值不做惩罚，排名是研究优先级而非个股推荐。</div></details><div className="chain-ranking">{chain.slice().sort((a, b) => b.strength - a.strength).map((item, index) => <div key={item.group}><em>{String(index + 1).padStart(2, "0")}</em><span><strong>{item.group}<b>{item.strength}</b></strong><small>{item.segment} · 成分 {item.constituents ?? item.leaders}</small><p>{item.signal}</p></span></div>)}</div></Panel><Panel title="全球大模型Token价格" kicker="MODEL ECONOMICS" className="span-3" action={<span className="pricing-updated">更新于 {pricingTime}</span>}><div className="model-price-note">价格单位：美元 / 100万Token；采用厂商官方标准API价格，长上下文、批处理、区域部署及工具调用可能另行计费。</div><div className="data-table model-price-table"><div className="table-row table-head"><span>厂商</span><span>模型</span><span>计价口径 / 上下文</span><span>输入</span><span>缓存输入</span><span>输出</span><span>适用方向</span><span>状态 / 来源</span></div>{(data.ai_model_pricing ?? []).map((item) => <a className="table-row" href={String(item.url)} target="_blank" rel="noreferrer" key={String(item.provider) + String(item.model)}><strong>{String(item.provider)}</strong><span className="mono">{String(item.model)}</span><small>{String(item.context)}</small><span className="mono price-cell">{String(item.input_per_m)}</span><span className="mono">{String(item.cached_input_per_m ?? "-")}</span><span className="mono price-cell">{String(item.output_per_m)}</span><small>{String(item.focus)}</small><span className="price-source"><StatusPill kind={String(item.price_status) === "官方实时" ? "positive" : "neutral"}>{String(item.price_status ?? "官方基准")}</StatusPill><ExternalLink size={12} /></span></a>)}</div></Panel></div>;
}

function CalendarPage({ data }: { data: DashboardData }) {
  const today = new Date(), todayStart = new Date(today.getFullYear(), today.getMonth(), today.getDate()), windowEnd = new Date(todayStart); windowEnd.setDate(windowEnd.getDate() + 30);
  const events = eventRows(data), [calendarOpen, setCalendarOpen] = useState(false), [selectedDate, setSelectedDate] = useState<string | null>(null), [visibleMonth, setVisibleMonth] = useState(() => new Date(today.getFullYear(), today.getMonth(), 1));
  const highEventCount = events.filter((item) => { const date = new Date(`${item.date}T00:00:00`); return item.importance === "高" && date >= todayStart && date <= windowEnd; }).length, year = visibleMonth.getFullYear(), month = visibleMonth.getMonth(), leading = new Date(year, month, 1).getDay(), days = new Date(year, month + 1, 0).getDate(), cells = Array.from({ length: leading + days }, (_, index) => index < leading ? null : index - leading + 1), monthLabel = new Intl.DateTimeFormat("zh-CN", { year: "numeric", month: "long" }).format(visibleMonth);
  const close = () => { setCalendarOpen(false); setSelectedDate(null); }, choose = (date: string) => { setSelectedDate(date); setCalendarOpen(false); window.setTimeout(() => document.getElementById(`event-${date}`)?.scrollIntoView({ behavior: "smooth", block: "center" }), 40); };
  useEffect(() => {
    const key = (event: KeyboardEvent) => { if (event.key === "Escape") close(); };
    const pointer = (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      if (calendarOpen && target.classList.contains("calendar-modal-backdrop")) close();
      else if (selectedDate && !calendarOpen && !target.closest(".calendar-list a") && !target.closest(".calendar-trigger")) setSelectedDate(null);
    };
    document.addEventListener("keydown", key);
    document.addEventListener("mousedown", pointer);
    return () => { document.removeEventListener("keydown", key); document.removeEventListener("mousedown", pointer); };
  }, [calendarOpen, selectedDate]);
  return <div className="page-grid calendar-page"><Panel title="未来高影响事件" kicker="EVENT CALENDAR" className="span-2"><div className="calendar-list">{events.map((item) => <a id={`event-${item.date}`} className={selectedDate === item.date ? "selected" : ""} href={item.source} target="_blank" rel="noreferrer" key={item.date + item.event}><time><strong>{item.date.slice(8)}</strong><span>{item.date.slice(0, 7)}</span></time><div><span>{item.region} · {item.source_name ?? "官方日历"}</span><strong>{item.event}</strong><small>影响：{item.assets}</small></div><StatusPill kind={item.importance === "高" ? "negative" : "neutral"}>{item.importance}</StatusPill><ExternalLink size={14} /></a>)}</div></Panel><Panel title="本期事件密度" kicker="RISK WINDOW"><button className="calendar-summary calendar-trigger" onClick={() => { setVisibleMonth(new Date(today.getFullYear(), today.getMonth(), 1)); setCalendarOpen(true); }}><CalendarDays size={28} /><strong>{highEventCount}</strong><span>未来30天高影响事件</span><small>数字表示从今天起30个自然日内的高影响事件数量。点击打开月历。</small></button></Panel>{calendarOpen && <div className="calendar-modal-backdrop"><section className="calendar-modal" role="dialog" aria-modal="true" aria-label="全球事件月历"><header><button aria-label="上一个月" onClick={() => setVisibleMonth(new Date(year, month - 1, 1))}><ChevronLeft size={18} /></button><div><span>EVENT CALENDAR</span><strong>{monthLabel}</strong></div><button aria-label="下一个月" onClick={() => setVisibleMonth(new Date(year, month + 1, 1))}><ChevronRight size={18} /></button><button className="calendar-close" aria-label="关闭月历" onClick={close}><X size={17} /></button></header><div className="calendar-weekdays">{["日", "一", "二", "三", "四", "五", "六"].map((day) => <span key={day}>{day}</span>)}</div><div className="calendar-month-grid">{cells.map((day, index) => { if (day === null) return <span className="calendar-empty" key={`empty-${index}`} />; const date = `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`, dayEvents = events.filter((item) => item.date === date), high = dayEvents.some((item) => item.importance === "高"); return <button className={selectedDate === date ? "active" : ""} disabled={!dayEvents.length} onClick={() => dayEvents.length && choose(date)} key={date}><span>{day}</span>{high && <i />}{dayEvents.length > 0 && <small>{dayEvents.length}项</small>}</button>; })}</div><footer><span><i />高影响事件</span><small>点击带标记日期可定位至对应事件。</small></footer></section></div>}</div>;
}

function CommodityPage({ data }: { data: DashboardData }) {
  const rows = data.commodity_market ?? [];
  const cftc = data.cftc_positions ?? [];
  const energy = data.eia_energy ?? [];
  const categories = ["全部", ...Array.from(new Set(rows.map((item) => item.category)))];
  const [category, setCategory] = useState("全部");
  const visible = category === "全部" ? rows : rows.filter((item) => item.category === category);
  const average = (values: Array<number | null | undefined>) => {
    const finite = values.filter((value): value is number => Number.isFinite(value));
    return finite.length ? finite.reduce((sum, value) => sum + value, 0) / finite.length : 0;
  };
  const categoryStats = Array.from(new Set(rows.map((item) => item.category))).map((label) => {
    const selected = rows.filter((item) => item.category === label);
    const values = selected.map((item) => item.change_20d).filter((value): value is number => Number.isFinite(value));
    return {
      label,
      count: selected.length,
      change: average(values),
      breadth: values.length ? values.filter((value) => value > 0).length / values.length * 100 : 0,
    };
  }).sort((a, b) => b.change - a.change);
  const allChanges = rows.map((item) => item.change_20d).filter((value): value is number => Number.isFinite(value));
  const stats = [{ label: "全部", count: rows.length, change: average(allChanges), breadth: allChanges.length ? allChanges.filter((value) => value > 0).length / allChanges.length * 100 : 0 }, ...categoryStats];
  const ranked = visible.filter((item) => Number.isFinite(item.change_20d)).slice().sort((a, b) => Number(b.change_20d) - Number(a.change_20d));
  const strongest = ranked[0];
  const weakest = ranked.at(-1);
  const highestVolatility = visible.filter((item) => Number.isFinite(item.volatility_20d)).slice().sort((a, b) => Number(b.volatility_20d) - Number(a.volatility_20d))[0];
  const highestRange = visible.filter((item) => Number.isFinite(item.range_percentile)).slice().sort((a, b) => Number(b.range_percentile) - Number(a.range_percentile))[0];
  const selectedMomentum = average(visible.map((item) => item.change_20d));
  const selectedBreadth = visible.length ? visible.filter((item) => Number(item.change_20d) > 0).length / visible.length * 100 : 0;
  const selectedVolatility = average(visible.map((item) => item.volatility_20d));
  const largestNetLong = cftc.slice().sort((a, b) => b.managed_money_net - a.managed_money_net)[0];
  const largestAddition = cftc.slice().sort((a, b) => b.weekly_change - a.weekly_change)[0];
  const largestReduction = cftc.slice().sort((a, b) => a.weekly_change - b.weekly_change)[0];
  const cftcLongBreadth = cftc.length ? cftc.filter((item) => item.managed_money_net > 0).length / cftc.length * 100 : 0;
  const inventoryChange = energy.length > 1 ? Number(energy[0].value) - Number(energy[1].value) : null;

  return <div className="page-grid commodity-page">
    <Panel title="商品板块温度" kicker="COMMODITY ROTATION" className="span-3">
      <div className="commodity-cards">{stats.map((item) => <button className={category === item.label ? "active" : ""} onClick={() => setCategory(item.label)} key={item.label}><span>{item.label === "全部" ? "全部商品" : item.label}<small>{item.count}个品种</small></span><strong className={tone(item.change)}>{pct(item.change)}</strong><em>20日上涨广度 {formatNumber(item.breadth, 0)}%</em></button>)}</div>
    </Panel>
    <Panel title="大宗商品全景" kicker="FUTURES MARKET" className="span-3" action={<StatusPill>{visible.length}个品种</StatusPill>}>
      <div className="commodity-filter" aria-label="大宗商品类别筛选">{categories.map((item) => <button className={category === item ? "active" : ""} onClick={() => setCategory(item)} key={item}>{item}</button>)}</div>
      <div className="commodity-overview">
        <div><span>当前筛选</span><strong>{category === "全部" ? "全部商品" : category}</strong></div>
        <div><span>20日平均涨跌</span><strong className={tone(selectedMomentum)}>{pct(selectedMomentum)}</strong></div>
        <div><span>上涨广度</span><strong>{formatNumber(selectedBreadth, 0)}%</strong></div>
        <div><span>平均20日波动</span><strong>{pct(selectedVolatility)}</strong></div>
        <div><span>阶段领涨</span><strong>{strongest?.name ?? "-"}</strong></div>
      </div>
      <div className="data-table commodity-table"><div className="table-row table-head"><span>品种</span><span>市场</span><span>最新价</span><span>1日</span><span>20日</span><span>60日</span><span>20日波动</span><span>一年区间</span><span>数据日 / 来源</span></div>{visible.map((item) => <a className="table-row" href={item.url} target="_blank" rel="noreferrer" key={item.symbol}><span><strong>{item.name}</strong><small>{item.symbol} · {item.category}</small></span><span>{item.market}</span><span className="mono">{formatNumber(item.price)}<small>{item.unit}</small></span><span className={tone(item.change_1d ?? 0)}>{pct(item.change_1d)}</span><span className={tone(item.change_20d ?? 0)}>{pct(item.change_20d)}</span><span className={tone(item.change_60d ?? 0)}>{pct(item.change_60d)}</span><span>{pct(item.volatility_20d)}</span><span><b className="range-track"><i style={{ width: `${Math.min(100, Math.max(0, item.range_percentile ?? 0))}%` }} /></b><small>{formatNumber(item.range_percentile, 0)}分位</small></span><span>{item.as_of}<small>{item.source}</small></span></a>)}</div>
      {category === "黑色系" && <p className="commodity-context"><strong>黑色系观察：</strong>螺纹钢连接地产与基建需求，热卷更偏制造业，铁矿石反映炉料成本和钢厂补库。三者应结合价差和方向共同判断，避免孤立解读单一品种。</p>}
    </Panel>
    <Panel title="CFTC管理基金仓位" kicker="POSITIONING" className="span-3">
      <div className="position-summary">
        <div><span>覆盖市场</span><strong>{cftc.length}</strong><small>CFTC周频品种</small></div>
        <div><span>净多市场占比</span><strong>{formatNumber(cftcLongBreadth, 0)}%</strong><small>管理基金净仓为正</small></div>
        <div><span>最大净多</span><strong>{largestNetLong?.name ?? "-"}</strong><small>{formatNumber(largestNetLong?.managed_money_net, 0)}手</small></div>
        <div><span>本周增仓最多</span><strong>{largestAddition?.name ?? "-"}</strong><small className="up">{formatNumber(largestAddition?.weekly_change, 0)}手</small></div>
        <div><span>本周减仓最多</span><strong>{largestReduction?.name ?? "-"}</strong><small className="down">{formatNumber(largestReduction?.weekly_change, 0)}手</small></div>
      </div>
      <div className="data-table cftc-table"><div className="table-row table-head"><span>品种 / 合约</span><span>净持仓</span><span>周变化</span><span>净仓 / 未平仓</span><span>未平仓量</span><span>数据日</span></div>{cftc.map((item) => <a className="table-row" href={item.url} target="_blank" rel="noreferrer" key={item.name}><span><strong>{item.name}</strong><small>{item.contract}</small></span><span className={tone(item.managed_money_net)}>{formatNumber(item.managed_money_net, 0)}</span><span className={tone(item.weekly_change)}>{formatNumber(item.weekly_change, 0)}</span><span className={tone(item.net_pct_open_interest ?? 0)}>{pct(item.net_pct_open_interest)}</span><span>{formatNumber(item.open_interest, 0)}</span><span>{item.as_of}<small>{item.frequency}</small></span></a>)}</div>
    </Panel>
    <Panel title="商品研究信号" kicker="CROSS-COMMODITY SIGNALS" className="span-2">
      <div className="commodity-signals">
        <div><span>20日最强</span><strong>{strongest?.name ?? "-"}</strong><em className="up">{pct(strongest?.change_20d)}</em></div>
        <div><span>20日最弱</span><strong>{weakest?.name ?? "-"}</strong><em className="down">{pct(weakest?.change_20d)}</em></div>
        <div><span>波动最高</span><strong>{highestVolatility?.name ?? "-"}</strong><em>{pct(highestVolatility?.volatility_20d)}</em></div>
        <div><span>一年位置最高</span><strong>{highestRange?.name ?? "-"}</strong><em>{formatNumber(highestRange?.range_percentile, 0)}分位</em></div>
      </div>
      <p className="large-note">强弱信号随上方筛选联动，用于快速识别板块内的趋势集中度、波动风险和拥挤位置。</p>
    </Panel>
    <Panel title="能源库存" kicker="EIA OFFICIAL">
      {inventoryChange !== null && <div className="energy-delta"><span>最新周度库存变化</span><strong className={tone(inventoryChange)}>{inventoryChange >= 0 ? "+" : ""}{formatNumber(inventoryChange, 0)}</strong><small>{String(energy[0]?.unit ?? "")}</small></div>}
      <div className="factor-list">{energy.map((item, index) => <div key={`${String(item.series_id ?? item.name)}-${index}`}><span>{String(item.name ?? item.series_id ?? "EIA指标")}<small>{String(item.date ?? item.period ?? "")}</small></span><strong>{formatNumber(item.value, 2)}</strong><em>{String(item.unit ?? "")}</em></div>)}</div>
    </Panel>
    <Panel title="来源与限制" kicker="DATA DISCIPLINE" className="span-3"><div className="method-grid"><div><strong>国际期货</strong><p>Yahoo Finance公开日线，用于价格、趋势、波动率与一年分位；属于公开但非交易所授权接口。</p></div><div><strong>中国黑色</strong><p>新浪财经连续期货公开日线，覆盖螺纹钢、热卷与铁矿石；连续价格不等于可直接交易合约。</p></div><div><strong>仓位</strong><p>CFTC官方Disaggregated COT周报，展示管理基金多空净仓及周变化，存在发布滞后。</p></div><div><strong>基本面</strong><p>EIA官方库存与供需数据已接入。当前不申请USDA FAS Key，因此不展示需要该权限的数据。</p></div></div></Panel>
  </div>;
}

export function TerminalDashboard({ section = "overview", detail }: { section?: string; detail?: string }) {
  const [data, setData] = useState<DashboardData>({}), [query, setQuery] = useState("");
  useEffect(() => { const base=document.querySelector("base")?.href; const url=base?new URL("data/latest.json",base):new URL("/data/latest.json",window.location.origin); fetch(url).then((response) => response.ok ? response.json() : Promise.reject()).then((payload) => setData(payload as DashboardData)).catch(() => {}); }, []);
  const history = (data.market_history?.length ?? 0) >= 6 ? data.market_history! : fallbackHistory;
  const suggestions = useMemo(() => { const value = query.trim().toLowerCase(); return value ? searchItems.filter((item) => `${item.label} ${item.code} ${item.category} ${item.keywords}`.toLowerCase().includes(value)).slice(0, 8) : []; }, [query]);
  const selectedScore=section==="allocation"&&detail?assetScores(data,history).find(item=>item.key===detail):undefined,isRegimeDetail=section==="regime"&&detail==="analysis",isCorrelationDetail=section==="correlation"&&detail==="methodology",[baseTitle,baseSubtitle]=sectionTitles[section]??sectionTitles.overview,title=selectedScore?`${selectedScore.asset}配置研究`:isRegimeDetail?"普林格周期判定审计":isCorrelationDetail?"跨资产相关性方法与审计":baseTitle,subtitle=selectedScore?"评分贡献、宏观验证、资金流、风险与历史校准":isRegimeDetail?"阶段拟合、底层代理、宏观验证、来源状态与可靠性边界":isCorrelationDetail?"共同交易日对齐、Pearson公式、多窗口结果与代理数据来源":baseSubtitle,generated=data.generated_at?new Date(data.generated_at).toLocaleString("zh-CN",{timeZone:"Asia/Shanghai"}):"缓存数据";
  let content: React.ReactNode;
  if (section === "allocation"&&detail) content=<AllocationDetailPage data={data} history={history} detail={detail}/>;
  else if (section === "allocation") content = <AllocationPage data={data} history={history} />;
  else if (isRegimeDetail) content=<PringDetailPage data={data} history={history}/>;
  else if (section === "regime") content = <RegimePage data={data} history={history} />;
  else if (isCorrelationDetail) content=<CorrelationDetailPage data={data} history={history}/>;
  else if (section === "correlation") content = <CorrelationPage data={data} history={history} />;
  else if (section === "markets") content = <div className="page-grid"><Panel title="全球市场轮动表" kicker="GLOBAL MARKET" className="span-3"><MarketsTable data={data} history={history} /></Panel></div>;
  else if (section === "etf-flows") content = <GlobalFlowsPage data={data} />;
  else if (section === "ai-chain") content = <AiPage data={data} />;
  else if (section === "calendar") content = <CalendarPage data={data} />;
  else if (section === "research") content = <CommodityPage data={data} />;
  else content = <OverviewPage data={data} history={history} />;
  return <div className="terminal-shell"><aside className="sidebar"><Link href="/" className="brand"><span>AA</span><div><strong>Asset Allocation</strong><small>Research Terminal</small></div></Link><nav>{navigation.map((item, index) => <Link className={section === item.key ? "active" : ""} href={item.href} key={item.key}><span>{String(index + 1).padStart(2, "0")}</span>{item.label}</Link>)}</nav><div className="sidebar-foot"><div><i className="online" /><span>数据服务正常</span></div><small>四小时自动更新</small></div></aside><main className="terminal-main"><header className="topbar"><div className="search-box"><Search size={16} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="搜索黄金、螺纹钢、US10Y、FOMC..." />{suggestions.length > 0 && <div className="suggestions">{suggestions.map((item) => <Link href={item.href} onClick={() => setQuery("")} key={item.id}><Search size={13} /><span><strong>{item.label}</strong><small>{item.code} · {item.category}</small></span><ChevronRight size={13} /></Link>)}</div>}</div><div className="top-actions"><span><RefreshCw size={14} />更新于 {generated}</span></div></header><div className="page-header"><div><span>GLOBAL ALLOCATION / {section.toUpperCase()}{detail?` / ${detail.toUpperCase()}`:""}</span><h1>{title}</h1><p>{subtitle}</p></div><div className="header-tags"><StatusPill kind="positive">公开数据</StatusPill><StatusPill>4H 更新</StatusPill></div></div><div className="terminal-content">{content}</div></main></div>;
}
